<?php
/** Shared POS/HRMS time clock. HRMS attendance is canonical; POS mirrors it. */
date_default_timezone_set('Asia/Manila'); session_start();
require_once '../config/db_connect.php'; require_once '../includes/auth_check.php';
requireAnyRole(['super_admin','cashier','inventory_staff'],'../auth/login.php');
$pos=getDB(); $hrms=getHrmsDB(); $uid=(int)$_SESSION['user_id']; $today=date('Y-m-d'); $msg=''; $msgType='success';
$csrf=$_SESSION['pos_time_csrf']??=bin2hex(random_bytes(24));
$pos->exec("ALTER TABLE users ADD COLUMN IF NOT EXISTS hrms_user_id INT NULL AFTER lastname");
$pos->exec("ALTER TABLE users ADD COLUMN IF NOT EXISTS hrms_employee_id INT NULL AFTER hrms_user_id");
$pos->exec("CREATE TABLE IF NOT EXISTS staff_attendance (id INT AUTO_INCREMENT PRIMARY KEY,pos_user_id INT NOT NULL,date DATE NOT NULL,time_in TIME NULL,time_out TIME NULL,hours_worked DECIMAL(5,2) NOT NULL DEFAULT 0,late_minutes INT NOT NULL DEFAULT 0,undertime_minutes INT NOT NULL DEFAULT 0,location_status VARCHAR(20) NOT NULL DEFAULT 'unknown',time_in_lat DECIMAL(10,7) NULL,time_in_lon DECIMAL(10,7) NULL,time_out_lat DECIMAL(10,7) NULL,time_out_lon DECIMAL(10,7) NULL,synced_at DATETIME NULL,UNIQUE KEY uq_staff_day(pos_user_id,date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
foreach(["ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS late_minutes INT NOT NULL DEFAULT 0 AFTER hours_worked","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS undertime_minutes INT NOT NULL DEFAULT 0 AFTER late_minutes","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS location_status VARCHAR(20) NOT NULL DEFAULT 'unknown' AFTER undertime_minutes","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_in_lat DECIMAL(10,7) NULL AFTER location_status","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_in_lon DECIMAL(10,7) NULL AFTER time_in_lat","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_out_lat DECIMAL(10,7) NULL AFTER time_in_lon","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_out_lon DECIMAL(10,7) NULL AFTER time_out_lat"] as $sql){try{$pos->exec($sql);}catch(Throwable $e){}}
$hrms->exec("ALTER TABLE attendance MODIFY employee_id INT NULL");
foreach(["ALTER TABLE attendance ADD COLUMN IF NOT EXISTS pos_user_id INT NULL AFTER user_id","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS source_system VARCHAR(30) NOT NULL DEFAULT 'hrms' AFTER pos_user_id","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS time_in_lat DECIMAL(10,7) NULL","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS time_in_lon DECIMAL(10,7) NULL","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS time_out_lat DECIMAL(10,7) NULL","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS time_out_lon DECIMAL(10,7) NULL","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS time_in_distance DECIMAL(10,2) NULL","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS time_out_distance DECIMAL(10,2) NULL","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS location_status VARCHAR(20) NOT NULL DEFAULT 'unknown'","ALTER TABLE attendance ADD COLUMN IF NOT EXISTS remote_deduction DECIMAL(10,2) NOT NULL DEFAULT 0"] as $sql){try{$hrms->exec($sql);}catch(Throwable $e){}}
$u=$pos->prepare('SELECT * FROM users WHERE id=?');$u->execute([$uid]);$pu=$u->fetch();
$hrUid=(int)($pu['hrms_user_id']??0);$empId=(int)($pu['hrms_employee_id']??0);
if(!$hrUid){$q=$hrms->prepare('SELECT u.id,u.employee_id FROM users u WHERE u.username=? OR (u.email=? AND ?<>\'\') LIMIT 1');$q->execute([$pu['username'],$pu['email']??'',$pu['email']??'']);if($x=$q->fetch()){$hrUid=(int)$x['id'];$empId=(int)($x['employee_id']??0);$pos->prepare('UPDATE users SET hrms_user_id=?,hrms_employee_id=? WHERE id=?')->execute([$hrUid,$empId?:null,$uid]);}}
$branch=null;if($empId){$q=$hrms->prepare('SELECT b.*,e.basic_salary FROM employees e LEFT JOIN branches b ON b.id=e.branch_id WHERE e.id=?');$q->execute([$empId]);$branch=$q->fetch();}
if(!$branch && $hrUid){$q=$hrms->prepare('SELECT b.*,0 basic_salary FROM users u LEFT JOIN branches b ON b.id=u.branch_id WHERE u.id=?');$q->execute([$hrUid]);$branch=$q->fetch();}
$radius=100.0;
function distm($a,$b,$c,$d){$R=6371000;$p1=deg2rad($a);$p2=deg2rad($c);$dp=deg2rad($c-$a);$dl=deg2rad($d-$b);$x=sin($dp/2)**2+cos($p1)*cos($p2)*sin($dl/2)**2;return $R*2*atan2(sqrt($x),sqrt(1-$x));}
function calcHours($d,$i,$o){return($i&&$o)?max(0,round((strtotime("$d $o")-strtotime("$d $i"))/3600,2)):0;}
function dailyDed($salary){return $salary>0?round($salary/22,2):0;}
function hrRow($db,$hrUid,$empId,$today){if($empId){$q=$db->prepare('SELECT * FROM attendance WHERE employee_id=? AND date=? LIMIT 1');$q->execute([$empId,$today]);}else{$q=$db->prepare('SELECT * FROM attendance WHERE user_id=? AND employee_id IS NULL AND date=? LIMIT 1');$q->execute([$hrUid,$today]);}return$q->fetch()?:null;}
function mirrorLocal($pos,$uid,$date,$r){if(!$r)return;$pos->prepare("INSERT INTO staff_attendance(pos_user_id,date,time_in,time_out,hours_worked,late_minutes,undertime_minutes,location_status,time_in_lat,time_in_lon,time_out_lat,time_out_lon,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE time_in=VALUES(time_in),time_out=VALUES(time_out),hours_worked=VALUES(hours_worked),late_minutes=VALUES(late_minutes),undertime_minutes=VALUES(undertime_minutes),location_status=VALUES(location_status),time_in_lat=VALUES(time_in_lat),time_in_lon=VALUES(time_in_lon),time_out_lat=VALUES(time_out_lat),time_out_lon=VALUES(time_out_lon),synced_at=NOW()")->execute([$uid,$date,$r['time_in'],$r['time_out'],$r['hours_worked']??0,$r['late_minutes']??0,$r['undertime_minutes']??0,$r['location_status']??'unknown',$r['time_in_lat']??null,$r['time_in_lon']??null,$r['time_out_lat']??null,$r['time_out_lon']??null]);}
$hrToday=$hrUid?hrRow($hrms,$hrUid,$empId,$today):null; if($hrToday)mirrorLocal($pos,$uid,$today,$hrToday);
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf_token']??''))){$msg='Invalid form submission.';$msgType='danger';}
 elseif(!$hrUid){$msg='This POS account is not linked to an HRMS employee/user yet. Assign it from HRMS/POS User Management first.';$msgType='danger';}
 else{
  $action=$_POST['action']??'';$r=hrRow($hrms,$hrUid,$empId,$today);$now=date('H:i:s');$lat=is_numeric($_POST['lat']??null)?(float)$_POST['lat']:null;$lon=is_numeric($_POST['lon']??null)?(float)$_POST['lon']:null;
  $d=null;$loc='unknown'; if($lat!==null&&$lon!==null&&!empty($branch['latitude'])&&!empty($branch['longitude'])){$d=round(distm($lat,$lon,(float)$branch['latitude'],(float)$branch['longitude']),2);$loc=$d<=$radius?'on_site':'remote';}
  if($action==='time_in' && (!$r||!$r['time_in'])){$late=max(0,(int)floor((strtotime("$today $now")-strtotime("$today 08:00:00"))/60));$status=$late>0?'late':'present';$remote=$loc==='remote'?dailyDed((float)($branch['basic_salary']??0)):0;
   if($r){$hrms->prepare("UPDATE attendance SET pos_user_id=?,source_system='pos',time_in=?,late_minutes=?,status=?,time_in_lat=?,time_in_lon=?,time_in_distance=?,location_status=?,remote_deduction=? WHERE id=?")->execute([$uid,$now,$late,$status,$lat,$lon,$d,$loc,$remote,$r['id']]);}
   else{$hrms->prepare("INSERT INTO attendance(user_id,employee_id,pos_user_id,source_system,date,time_in,late_minutes,status,time_in_lat,time_in_lon,time_in_distance,location_status,remote_deduction) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$hrUid,$empId?:null,$uid,'pos',$today,$now,$late,$status,$lat,$lon,$d,$loc,$remote]);}$msg='Time In recorded and reflected in HRMS.';
  }elseif($action==='time_out'&&$r&&$r['time_in']&&!$r['time_out']){$under=max(0,(int)floor((strtotime("$today 17:00:00")-strtotime("$today $now"))/60));$finalLoc=(($r['location_status']??'')==='remote'||$loc==='remote')?'remote':($loc==='on_site'?'on_site':($r['location_status']??'unknown'));$remote=(float)($r['remote_deduction']??0);if($finalLoc==='remote'&&$remote<=0)$remote=dailyDed((float)($branch['basic_salary']??0));$hours=calcHours($today,$r['time_in'],$now);$hrms->prepare("UPDATE attendance SET pos_user_id=?,source_system='pos',time_out=?,hours_worked=?,undertime_minutes=?,time_out_lat=?,time_out_lon=?,time_out_distance=?,location_status=?,remote_deduction=? WHERE id=?")->execute([$uid,$now,$hours,$under,$lat,$lon,$d,$finalLoc,$remote,$r['id']]);$msg='Time Out recorded and reflected in HRMS.';
  }else{$msg='That time-clock action is not available because the shared attendance record is already updated.';$msgType='warning';}
  $r=hrRow($hrms,$hrUid,$empId,$today);mirrorLocal($pos,$uid,$today,$r);$hrToday=$r;
 }
}
$st=$pos->prepare('SELECT * FROM staff_attendance WHERE pos_user_id=? AND date=?');$st->execute([$uid,$today]);$todayRow=$st->fetch();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Time In / Out — Boba House POS</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css"><link rel="stylesheet" href="../assets/css/custom.css"></head><body><div class="d-flex" style="min-height:100vh"><?php include '../includes/sidebar.php';?><main id="main-content"><div class="topbar"><h1 class="page-title"><i class="bi bi-clock-fill me-2"></i>Shared Time In / Out</h1><span><?=date('F j, Y')?></span></div><div class="content-area">
<?php if($msg):?><div class="alert alert-<?=$msgType?>"><?=htmlspecialchars($msg)?></div><?php endif;?>
<div class="alert alert-info small"><strong>One attendance record:</strong> you can Time In on HRMS and Time Out here, or the other way around. Both systems read the same HRMS record. Location is checked against <strong><?=htmlspecialchars($branch['name']??'assigned branch / NCST')?></strong>; outside the geofence creates a payroll deduction, and late minutes are recorded.</div>
<div class="row justify-content-center"><div class="col-lg-7"><div class="card shadow-sm"><div class="card-body text-center p-5"><div class="display-5 fw-bold mb-2" id="clock"><?=date('g:i:s A')?></div><div class="text-muted mb-3"><?=htmlspecialchars($branch['name']??'Assigned branch / NCST')?> · <?=($todayRow['location_status']??'unknown')==='remote'?'Outside location':ucwords(str_replace('_',' ',$todayRow['location_status']??'unknown'))?></div>
<?php if(!$todayRow||!$todayRow['time_in']):?><form method="post" id="clockForm"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="time_in"><input type="hidden" name="lat" id="lat"><input type="hidden" name="lon" id="lon"><button class="btn btn-success btn-lg px-5" onclick="return withGps(this.form)"><i class="bi bi-box-arrow-in-right me-2"></i>Time In</button></form>
<?php elseif(!$todayRow['time_out']):?><p>Time In: <strong><?=date('g:i A',strtotime($todayRow['time_in']))?></strong><?php if($todayRow['late_minutes']):?> · <span class="text-warning"><?=$todayRow['late_minutes']?> min late</span><?php endif;?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="action" value="time_out"><input type="hidden" name="lat"><input type="hidden" name="lon"><button class="btn btn-danger btn-lg px-5" onclick="return withGps(this.form)"><i class="bi bi-box-arrow-right me-2"></i>Time Out</button></form>
<?php else:?><p class="mb-1">Time In: <strong><?=date('g:i A',strtotime($todayRow['time_in']))?></strong></p><p>Time Out: <strong><?=date('g:i A',strtotime($todayRow['time_out']))?></strong></p><span class="badge bg-success">Synced with HRMS</span><?php if(($todayRow['location_status']??'')==='remote'):?><span class="badge bg-danger ms-1">Outside geofence — deduction</span><?php endif;?><?php endif;?>
</div></div></div></div></div></main></div><script>setInterval(()=>document.getElementById('clock').textContent=new Date().toLocaleTimeString('en-PH'),1000);function withGps(f){if(!navigator.geolocation)return true;navigator.geolocation.getCurrentPosition(p=>{f.querySelector('[name=lat]').value=p.coords.latitude;f.querySelector('[name=lon]').value=p.coords.longitude;f.submit()},()=>f.submit(),{enableHighAccuracy:true,timeout:5000});return false;}</script></body></html>
